package com.activegoals;

import java.util.ArrayDeque;
import java.util.Deque;
import java.util.EnumMap;
import java.util.Locale;
import java.util.Map;
import java.util.regex.Matcher;
import java.util.regex.Pattern;

/** Transient, client-thread-confined observations of Mahogany Homes contracts. */
final class MahoganyHomesTracker
{
    private static final int SAMPLE_LIMIT = 20;
    private static final long NANOS_PER_SECOND = 1_000_000_000L;
    // Message formats were checked against the Mahogany Homes Plugin Hub plugin:
    // https://github.com/TheStonedTurtle/Mahogany-Homes/blob/master/src/main/java/thestonedturtle/mahoganyhomes/MahoganyHomesPlugin.java
    private static final Pattern ASSIGNMENT = Pattern.compile(
        "^(Beginner|Novice|Adept|Expert) Contract: Go see .+\\.$", Pattern.CASE_INSENSITIVE);
    private static final Pattern COMPLETION = Pattern.compile(
        "^You have completed [0-9,]+ contracts with a total of [0-9,]+ points?\\.$");

    private enum Tier { BEGINNER, NOVICE, ADEPT, EXPERT }

    private final Map<Tier, Deque<Integer>> samples = new EnumMap<>(Tier.class);
    private Tier currentTier;
    private Tier activeTier;
    private int activeStartXp;
    private boolean activeValid;
    private boolean pendingCompletion;
    private Tier pendingTier;
    private int pendingStartXp;
    private boolean pendingValid;
    private long pendingNanos;
    private int knownOutfit = -1;
    private boolean outfitAvailable;
    private boolean estimateActive;
    private int lastCompletionXp;
    private long lastCompletionNanos;

    /** The mask identifies only equipped Carpenter's outfit pieces; -1 means unavailable. */
    boolean observeOutfit(int mask)
    {
        if (mask < 0)
        {
            boolean changed = outfitAvailable;
            outfitAvailable = false;
            activeValid = false;
            pendingValid = false;
            return changed;
        }
        boolean changed = !outfitAvailable || (knownOutfit >= 0 && knownOutfit != mask);
        if (knownOutfit >= 0 && knownOutfit != mask)
        {
            samples.clear();
            activeValid = false;
            pendingValid = false;
            estimateActive = false;
        }
        knownOutfit = mask;
        outfitAvailable = true;
        return changed;
    }

    /** Observe a tag-stripped GAMEMESSAGE after login and profile initialization. */
    boolean observeMessage(String message, int xp, int outfitMask, long nowNanos)
    {
        boolean changed = observeOutfit(outfitMask);
        if (message == null) return changed;
        Matcher assignment = ASSIGNMENT.matcher(message);
        if (assignment.matches())
        {
            Tier next = Tier.valueOf(assignment.group(1).toUpperCase(Locale.ROOT));
            boolean overlap = activeTier != null || pendingCompletion;
            if (pendingCompletion) pendingValid = false;
            currentTier = next;
            activeTier = next;
            activeStartXp = xp;
            // An overlapping assignment is ambiguous; never sample a partial contract.
            activeValid = !overlap && xp >= 0 && outfitAvailable;
            return true;
        }
        if (COMPLETION.matcher(message).matches() && !pendingCompletion && activeTier != null)
        {
            pendingCompletion = true;
            pendingTier = activeTier;
            pendingStartXp = activeStartXp;
            pendingValid = activeValid && outfitAvailable && xp >= activeStartXp;
            pendingNanos = nowNanos;
            activeTier = null;
            activeValid = false;
            return true;
        }
        return changed;
    }

    /** Finish an observed completion on the next game tick, after the completion XP update. */
    boolean onTick(int xp, int outfitMask, long nowNanos)
    {
        boolean changed = observeOutfit(outfitMask);
        if (activeTier != null && xp < activeStartXp) activeValid = false;
        if (!pendingCompletion) return changed;
        if (pendingValid && outfitAvailable && xp > pendingStartXp)
        {
            Deque<Integer> values = samples.computeIfAbsent(pendingTier, ignored -> new ArrayDeque<>());
            values.addLast(xp - pendingStartXp);
            if (values.size() > SAMPLE_LIMIT) values.removeFirst();
        }
        if (xp >= 0 && outfitAvailable)
        {
            lastCompletionXp = xp;
            lastCompletionNanos = pendingNanos;
            estimateActive = true;
        }
        pendingCompletion = false;
        pendingTier = null;
        pendingValid = false;
        return true;
    }

    /** Estimates are fixed at the last completion XP; they do not change during repairs. */
    long estimateHomes(long targetXp, long nowNanos, int timeoutSeconds)
    {
        if (!estimateActive || !outfitAvailable || currentTier == null || timeoutSeconds <= 0) return -1;
        long elapsed = nowNanos - lastCompletionNanos;
        if (elapsed < 0 || elapsed >= timeoutSeconds * NANOS_PER_SECOND)
        {
            estimateActive = false;
            return -1;
        }
        Deque<Integer> values = samples.get(currentTier);
        if (values == null || values.isEmpty()) return -1;
        long total = 0;
        for (int value : values) total += value;
        long remaining = Math.max(0, targetXp - lastCompletionXp);
        return (long) Math.ceil((double) remaining * values.size() / total);
    }

    void reset()
    {
        samples.clear();
        currentTier = null;
        activeTier = null;
        activeValid = false;
        pendingCompletion = false;
        pendingTier = null;
        pendingValid = false;
        knownOutfit = -1;
        outfitAvailable = false;
        estimateActive = false;
        lastCompletionXp = 0;
        lastCompletionNanos = 0;
    }
}

package com.activegoals;

import org.junit.jupiter.api.Test;
import java.lang.reflect.Field;
import java.util.ArrayDeque;
import java.util.Deque;
import java.util.EnumMap;
import java.util.Map;
import net.runelite.api.Skill;
import static org.junit.jupiter.api.Assertions.assertTrue;
import java.util.Arrays;
import java.util.Collections;
import static org.junit.jupiter.api.Assertions.assertEquals;

class ActiveGoalsActionsLeftTest
{
    @Test void noSamplesWaitsForXp() { assertEquals(-1, ActiveGoalsPlugin.estimateActionsLeft(1000, Collections.emptyList())); }
    @Test void averagesRecentXpGains() { assertEquals(7, ActiveGoalsPlugin.estimateActionsLeft(1000, Arrays.asList(100, 200))); }
    @Test void completedGoalShowsZero() { assertEquals(0, ActiveGoalsPlugin.estimateActionsLeft(0, Collections.emptyList())); }
    @Test void roundsUpActions() { assertEquals(4, ActiveGoalsPlugin.estimateActionsLeft(301, Arrays.asList(100))); }
    @Test void resetClearsOnlyActionSamples() throws Exception
    {
        ActiveGoalsPlugin plugin = new ActiveGoalsPlugin();
        Field field = ActiveGoalsPlugin.class.getDeclaredField("recentXpGainSamples");
        field.setAccessible(true);
        @SuppressWarnings("unchecked")
        Map<Skill, Deque<Integer>> samples = (Map<Skill, Deque<Integer>>) field.get(plugin);
        samples.put(Skill.WOODCUTTING, new ArrayDeque<>(Arrays.asList(100, 120)));
        assertEquals(10, plugin.getActionsLeft(Skill.WOODCUTTING, 1000));
        plugin.clearActionSamples();
        assertTrue(samples.isEmpty());
        assertEquals(-1, plugin.getActionsLeft(Skill.WOODCUTTING, 1000));
    }
}

package com.activegoals;

import java.util.HashSet;
import java.util.Set;
import net.runelite.client.config.ConfigGroup;
import net.runelite.client.config.ConfigItem;
import net.runelite.client.config.Range;
import org.junit.jupiter.api.Test;
import static org.junit.jupiter.api.Assertions.*;

class ActiveGoalsConfigTest
{
    @Test
    void nativeSettingsUseExistingKeysAndDelayBounds() throws Exception
    {
        assertEquals("activegoals", ActiveGoalsConfig.class.getAnnotation(ConfigGroup.class).value());
        Set<String> keys = new HashSet<>();
        for (java.lang.reflect.Method method : ActiveGoalsConfig.class.getDeclaredMethods())
        {
            ConfigItem item = method.getAnnotation(ConfigItem.class);
            if (item != null) keys.add(item.keyName());
        }
        assertEquals(Set.of("goalCardExpansionSeconds", "goalOrderingActivitySeconds", "agilityLapTimeoutSeconds", "homesTimeoutSeconds"), keys);
        assertEquals(ActiveGoalsConfig.COLLAPSE_SECTION,
            ActiveGoalsConfig.class.getMethod("goalCardExpansionSeconds").getAnnotation(ConfigItem.class).section());
        Range range = ActiveGoalsConfig.class.getMethod("goalCardExpansionSeconds").getAnnotation(Range.class);
        assertEquals(1, range.min());
        assertEquals(86400, range.max());
        assertEquals(ActiveGoalsConfig.ORDER_SECTION,
            ActiveGoalsConfig.class.getMethod("goalOrderingActivitySeconds").getAnnotation(ConfigItem.class).section());
        Range orderingRange = ActiveGoalsConfig.class.getMethod("goalOrderingActivitySeconds").getAnnotation(Range.class);
        assertEquals(1, orderingRange.min());
        assertEquals(86400, orderingRange.max());
        assertEquals(ActiveGoalsConfig.AGILITY_SECTION,
            ActiveGoalsConfig.class.getMethod("agilityLapTimeoutSeconds").getAnnotation(ConfigItem.class).section());
        Range agilityRange = ActiveGoalsConfig.class.getMethod("agilityLapTimeoutSeconds").getAnnotation(Range.class);
        assertEquals(1, agilityRange.min());
        assertEquals(86400, agilityRange.max());
        assertEquals(ActiveGoalsConfig.HOMES_SECTION,
            ActiveGoalsConfig.class.getMethod("homesTimeoutSeconds").getAnnotation(ConfigItem.class).section());
        Range homesRange = ActiveGoalsConfig.class.getMethod("homesTimeoutSeconds").getAnnotation(Range.class);
        assertEquals(1, homesRange.min());
        assertEquals(86400, homesRange.max());
    }
}

